prompt:
Create unit `tasks` and implement `all_in_range`: return whether every element of `a` lies in [lo, hi]. The contract must state the result exactly (true if and only if all elements are in range).

Required signature (in unit `tasks`):
fn all_in_range(a: &[i64], lo: i64, hi: i64) -> (r: bool)

reference.code:
spec fn in_below(a: &[i64], lo: i64, hi: i64, n: usize) -> bool { forall|k: usize| k < n ==> lo <= #[trigger] a[k] && a[k] <= hi }

spec fn all_in(a: &[i64], lo: i64, hi: i64, r: bool) -> bool { r == (forall|k: usize| k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi) }

#[effects(pure)]
#[uses(in_below, all_in)]
fn all_in_range(a: &[i64], lo: i64, hi: i64) -> (r: bool)
    ensures all_in(a, lo, hi, r),
{
    let mut k: usize = 0;
    while k < a.len() && lo <= a[k] && a[k] <= hi
        invariant k <= a.len(), in_below(a, lo, hi, k),
        decreases a.len() - k,
    {
        k = k + 1;
    }
    k >= a.len()
}

